// Logo KEU LOCA MOTOS — PNG 250px embarcado como base64.
// Convertido de public/logos/keu-loca-motos.webp:
//   sips -s format png public/logos/keu-loca-motos.webp --out /tmp/logo.png
//   sips -Z 250 /tmp/logo.png --out /tmp/logo-250.png
//   base64 -i /tmp/logo-250.png | tr -d '\n' | pbcopy
//
// React-pdf v4 não renderiza WebP de forma confiável em Vercel Lambda
// (~6s timeout sem erro visível). PNG funciona.
// 250px é suficiente pro header do contrato (renderizado a 220px no PDF).
export const KEU_LOGO_DATA_URL = "data:image/png;base64,";
